DROP VIEW catalog_discovery;
DROP VIEW catalog_version_metadata;
CREATE VIEW catalog_version_metadata AS SELECT v.*,COALESCE(m.model_type,CASE lower(COALESCE(json_extract(v.subject,'$.recipe.id'),CASE WHEN instr(v.title,'--')>0 THEN substr(v.title,1,instr(v.title,'--')-1) ELSE '' END)) WHEN 'smithy' THEN 'Buildings' WHEN 'fruit-stall' THEN 'Props' WHEN 'young-ember' THEN 'Nature' WHEN 'hydrangea' THEN 'Nature' WHEN 'crossroads-oak' THEN 'Nature' WHEN 'conifer' THEN 'Nature' WHEN 'porcini' THEN 'Nature' WHEN 'pier' THEN 'Structures' ELSE NULL END) AS model_type,m.style_id,CASE WHEN m.recipe_id IS NULL THEN 'unclassified' ELSE 'registered-recipe' END AS metadata_source FROM asset_version v LEFT JOIN catalog_recipe_metadata m ON json_extract(v.subject,'$.recipe.id')=m.recipe_id AND json_extract(v.subject,'$.recipe.version')=m.recipe_version AND json_extract(v.subject,'$.selectedDesign.family')=m.recipe_id AND json_extract(v.subject,'$.selectedDesign.familyVersion')=m.recipe_version;
CREATE VIEW catalog_discovery AS SELECT v.* FROM catalog_version_metadata v WHERE v.state='published' AND NOT EXISTS(SELECT 1 FROM asset_version newer WHERE newer.asset_id=v.asset_id AND newer.state='published' AND (COALESCE(newer.published_at,0)>COALESCE(v.published_at,0) OR (COALESCE(newer.published_at,0)=COALESCE(v.published_at,0) AND newer.id>v.id)));
